package com.hotel.controller;
import com.hotel.dao.impl.RoomDaoImpl;import com.hotel.exception.*;import com.hotel.service.RoomAvailabilityService;import com.hotel.service.impl.RoomAvailabilityServiceImpl;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.time.LocalDate;
@WebServlet("/receptionist/rooms/available") public class AvailableRoomServlet extends HttpServlet{
 private final RoomAvailabilityService service=new RoomAvailabilityServiceImpl(new RoomDaoImpl());
 protected void doGet(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{try{q.setAttribute("roomTypes",service.roomTypes());String rawIn=q.getParameter("checkIn"),rawOut=q.getParameter("checkOut");if(rawIn!=null&&!rawIn.isBlank()&&rawOut!=null&&!rawOut.isBlank()){LocalDate checkIn=LocalDate.parse(rawIn),checkOut=LocalDate.parse(rawOut);Long type=parseLong(q.getParameter("roomTypeId"));int adults=parseInt(q.getParameter("adults"),1),children=parseInt(q.getParameter("children"),0);Integer floor=parseInteger(q.getParameter("floor"));q.setAttribute("rooms",service.search(checkIn,checkOut,type,adults,children,floor));q.setAttribute("searched",true);}}catch(java.time.format.DateTimeParseException|NumberFormatException e){q.setAttribute("lookupError","Thông tin tìm kiếm không hợp lệ.");s.setStatus(400);}catch(BusinessException e){q.setAttribute("lookupError",e.getMessage());s.setStatus(400);}catch(DataAccessException e){getServletContext().log("Room availability failed",e);s.sendError(500);return;}q.getRequestDispatcher("/WEB-INF/views/receptionist/rooms/available.jsp").forward(q,s);}
 private Long parseLong(String x){return x==null||x.isBlank()?null:Long.valueOf(x);}private Integer parseInteger(String x){return x==null||x.isBlank()?null:Integer.valueOf(x);}private int parseInt(String x,int d){return x==null||x.isBlank()?d:Integer.parseInt(x);}
}
